<script setup lang="ts">
import type { useStudentSearch } from '../composables/useStudentSearch';import CodeSelect from '../components/CodeSelect.vue';import MessagePanel from '../components/MessagePanel.vue';import StudentGrid from '../components/StudentGrid.vue';import Pager from '../components/Pager.vue';
defineProps<{ state:ReturnType<typeof useStudentSearch> }>();defineEmits<{ open:[id:string|null] }>();
</script>
<template><h1>学生検索</h1><MessagePanel :message="state.message.value" :error="state.error.value"/><p v-if="state.changed.value" class="warning">条件を変更しました。検索結果への反映には「検索」を押してください。</p><form @submit.prevent="state.search"><fieldset :disabled="state.busy.value || !state.bootstrap.value"><legend>検索条件</legend><div class="fields"><label>学籍番号<input id="SRC-001" v-model="state.draft.studentNo" maxlength="30"></label><label>氏名<input id="SRC-002" v-model="state.draft.name" maxlength="16"></label><label>氏名カナ<input id="SRC-003" v-model="state.draft.kana" maxlength="72"></label><label>年度<select id="SRC-004" v-model="state.draft.schoolYear" :disabled="state.draft.unassignedOnly" @change="state.options"><option :value="null">すべて</option><option v-for="y in state.lookups.value.years" :key="y" :value="y">{{y}}</option></select></label><label>学年<CodeSelect id="SRC-005" v-model="state.draft.gradeCode" :items="state.lookups.value.codes" category="GRADE" search empty-label="すべて" :disabled="state.draft.unassignedOnly" @update:model-value="state.options"/></label><label>クラス<select id="SRC-006" v-model="state.draft.classId" :disabled="state.draft.unassignedOnly"><option :value="null">すべて</option><option v-for="c in state.lookups.value.classes" :key="c.classId" :value="c.classId">{{c.schoolYear}} {{c.gradeName}} {{c.classCode}} {{c.className}} {{c.note}}</option></select></label><label class="check"><input id="SRC-007" v-model="state.draft.unassignedOnly" type="checkbox" @change="state.unassigned">未所属のみ</label><fieldset><legend>在籍区分</legend><label v-for="code in state.lookups.value.codes.filter(c=>c.categoryId==='ENROLLMENT_STATUS')" :key="code.value" class="check"><input v-model="state.draft.statusCodes" type="checkbox" :value="code.value">{{code.name}}</label><small>全解除はすべて</small></fieldset><label>都道府県<CodeSelect id="SRC-009" v-model="state.draft.prefectureCode" :items="state.lookups.value.codes" category="PREFECTURE" search empty-label="すべて"/></label><label>電話番号<input id="SRC-010" v-model="state.draft.phoneNumber" maxlength="40"></label><label>入学日・開始<input id="SRC-011" v-model="state.draft.admissionFrom" type="date"></label><label>入学日・終了<input id="SRC-012" v-model="state.draft.admissionTo" type="date"></label></div><div class="actions"><button type="submit" class="primary">検索</button><button type="button" @click="state.clear">クリア</button><button v-if="state.bootstrap.value?.permissions.create" type="button" @click="$emit('open',null)">新規登録</button></div></fieldset></form><template v-if="state.result.value"><p>{{state.result.value.totalCount===null?'未検索／上限超過':`検索結果 ${state.result.value.totalCount}件`}} {{state.result.value.searchedAt}}</p><div class="actions"><label>表示件数<select v-model="state.pageSize.value" :disabled="state.busy.value" @change="state.page(1)"><option :value="20">20</option><option :value="50">50</option><option :value="100">100</option></select></label><label>並び順<select v-model="state.sortKey.value" :disabled="state.busy.value" @change="state.page(1)"><option value="studentNo">学籍番号</option><option value="name">氏名</option><option value="admissionDate">入学日</option><option value="updatedAt">更新日時</option></select></label><select v-model="state.sortDirection.value" aria-label="並び順方向" :disabled="state.busy.value" @change="state.page(1)"><option value="asc">昇順</option><option value="desc">降順</option></select></div><StudentGrid :items="state.result.value.items" :busy="state.busy.value" :can-update="state.bootstrap.value?.permissions.update || false" @open="$emit('open',$event)"/><Pager :page="state.result.value.page" :total-count="state.result.value.totalCount" :page-size="state.result.value.pageSize" :disabled="state.busy.value || state.result.value.outcome!=='found'" @move="state.page"/></template></template>
